interface.definition:
a!localVariables(
  /*ri!isOldVersion: if(*/
  /*a!isNullOrEmpty(ri!nomination.createdOn),*/
  /*false,*/
  /*if(*/
  /*todatetime(ri!nomination.createdOn) < cons!DRT_V3_DEPLOYMENT_DATE_TIME,*/
  /*true,*/
  /*false*/
  /*)*/
  /*),*/
  /*local!isRequestBeforeV4: if(*/
  /*a!isNullOrEmpty(ri!nomination.createdOn),*/
  /*false,*/
  /*if(*/
  /*todatetime(ri!nomination.createdOn) < cons!DRT_V4_DEPLOYMENT_DATE_TIME,*/
  /*true,*/
  /*false*/
  /*)*/
  /*),*/
  local!selectedReviewerGroup,
  local!nonAuditLeaders: a!groupMembers(
    group: #"_a-0000e825-ace1-8000-9c24-011c48011c48_6790160",
    direct: true,
    memberType: "USER"
  ),
  local!nonAuditLeadersList: index(local!nonAuditLeaders, "data", {}),
  local!nonAuditLeadersCount: index(local!nonAuditLeaders, "totalCount", {}),
  local!listOfBUPPP_BUPIC: reject(
    fn!isnull,
    #"SYSTEM_SYSRULES_forEach"(
      items: if(
        contains(
          {
            #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694208",
            #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694215",
            #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4244284",
            #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558152",
            #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362543"
          },
          tostring(local!selectedReviewerGroup)
        ),
        if(
          tostring(local!selectedReviewerGroup) = #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694208",
          if(
            ri!nomination.nominationTypeId = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
            #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3691497",
            if(
              ri!isOldVersion = true,
              #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3691497",
              #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11716024"
            )
          ),
          if(
            tostring(local!selectedReviewerGroup) = #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694215",
            if(
              ri!nomination.nominationTypeId = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
              #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3691504",
              if(
                ri!isOldVersion = true,
                #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3691504",
                #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11718114"
              )
            ),
            if(
              tostring(local!selectedReviewerGroup) = #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558152",
              if(
                ri!nomination.nominationTypeId = #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3868562",
                #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558110",
                if(
                  ri!isOldVersion = true,
                  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558110",
                  #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11718806"
                )
              ),
              if(
                tostring(local!selectedReviewerGroup) = #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362543",
                #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362557",
                #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4244182"
              )
            )
          )
        ),
        null
      ),
      expression: fv!item
      /*if(*/
        /*tointeger(*/
          /*a!groupMembers(*/
            /*a!groupsByName(tostring(rule!CAW_prependCAW(fv!item)))*/
          /*).totalCount*/
        /*) <> 0,*/
        /*fv!item,*/
        /*null*/
      /*)*/
    )
  ),
  local!selectedBUPPP_BUPIC,
  local!isRequestAfterV4: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  #"SYSTEM_SYSRULES_cardLayout"(
    contents: {
      #"SYSTEM_SYSRULES_columnsLayout"(
        showDividers: true,
        columns: {
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: "Select Reviewer1",
                placeholder: "Select Reviewer",
                choiceLabels: ri!listOfReviewers,
                choiceValues: ri!listOfReviewers,
                value: local!selectedReviewerGroup,
                saveInto: {
                  local!selectedReviewerGroup,
                  a!save(ri!selectedGroup, save!value),
                  a!save(local!selectedBUPPP_BUPIC, null),
                  a!save(ri!selectedBUPPP_BUPIC, null),
                  a!save(ri!selectedBuReviewer, null)
                },
                disabled: contains(
                  #"SYSTEM_SYSRULES_forEach"(
                    items: if(
                      ri!nomination.isReapprovedByBU = true,
                      remove(
                        #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472370",
                        5
                      ),
                      if(
                        ri!nomination.isOpsAdditionalVettingReq = true,
                        remove(
                          #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472370",
                          7
                        ),
                        #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472370"
                      )
                    ),
                    expression: index(ri!nomination, fv!item, toboolean({}))
                  ),
                  true
                ),
                validations: if(
                  and(
                    ri!nomination.isReapprovedByBU = true,
                    #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                      ri!nomination.isReapprovedByBUCompleted
                    ),
                    not(
                      contains(
                        {
                          "Non-Audit Leaders",
                          "BUPPP",
                          "BUPIC",
                          "BUCoS",
                          "BUPPP_BUPIC",
                          "BUCoS_Delegate"
                        },
                        local!selectedReviewerGroup
                      )
                    ),
                    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!selectedReviewerGroup)
                  ),
                  "Please Select a BU Group for BU Reapproval",
                  if(
                    and(
                      ri!nomination.isOpsAdditionalVettingReq = true,
                      #"_a-0000e382-8b6f-8000-9ba2-011c48011c48_32623"(
                        ri!nomination.isOpsAdditionalVettingReqCompleted
                      ),
                      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!selectedReviewerGroup)
                    ),
                    if(
                      toboolean(ri!isOldVersion) = true,
                      if(
                        not(
                          contains(
                            touniformstring(
                              {
                                "PPL",
                                "DPP PIC",
                                "WRPPP",
                                "ERPPP",
                                "Deputy PPL"
                              }
                            ),
                            tostring(ri!selectedGroup)
                          )
                        ),
                        "Please select PPL, Deputy PPL, DPP PIC, APPP, group for additional Operations vetting",
                        ""
                      ),
                      if(
                        not(
                          contains(
                            touniformstring(
                              {
                                "PPL",
                                "DPP PIC",
                                /*"RPPP",*/
                                "APPP",
                                "Deputy PPL",
                                "PPL Delegate MD Rotational",
                                "PPL Delegate ALL",

                              }
                            ),
                            tostring(ri!selectedGroup)
                          )
                        ),
                        "Please select PPL, Deputy PPL, DPP PIC,PPL Delegate ALL,PPL Delegate MD Rotational, or APPP group for additional Operations vetting",
                        ""
                      )
                    ),
                    if(
                      and(
                        local!selectedReviewerGroup = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
                        local!nonAuditLeadersCount < 1
                      ),
                      "Please select a different reviewer",
                      null
                    )
                  )
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_dropdownField_v1"(
                label: if(
                  local!isRequestAfterV4,
                  "Select Reviewer",
                  "Select BUPPP/BUPIC/BUCoS"
                ),
                placeholder: "Select Reviewer",
                choiceLabels: if(
                  local!selectedReviewerGroup = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3052910"(local!nonAuditLeadersList),
                  local!listOfBUPPP_BUPIC
                ),
                choiceValues: if(
                  local!selectedReviewerGroup = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
                  local!nonAuditLeadersList,
                  local!listOfBUPPP_BUPIC
                ),
                value: local!selectedBUPPP_BUPIC,
                saveInto: {
                  local!selectedBUPPP_BUPIC,
                  a!save(ri!selectedBUPPP_BUPIC, save!value),
                  a!save(ri!selectedBuReviewer, save!value)
                },
                disabled: or(
                  not(
                    contains(
                      {
                        #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694208",
                        #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694215",
                        #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4244284",
                        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558152",
                        #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
                        #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362543"
                      },
                      local!selectedReviewerGroup
                    )
                  ),
                  and(
                    local!selectedReviewerGroup = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
                    local!nonAuditLeadersCount < 1
                  )
                ),
                required: contains(
                  {
                    #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694208",
                    #"_a-0000e6ca-52ed-8000-9bff-011c48011c48_3694215",
                    #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4244284",
                    #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4558152",
                    #"_a-0000e825-ace1-8000-9c24-011c48011c48_6801187",
                    #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362543"
                  },
                  local!selectedReviewerGroup
                )
              )
            }
          ),
          #"SYSTEM_SYSRULES_columnLayout"(
            contents: {
              #"SYSTEM_SYSRULES_checkboxField"(
                label: "Nomination process completed",
                choiceLabels: "",
                choiceValues: { true },
                value: index(
                  ri!nomination,
                  "isReadyForOnboarding",
                  toboolean(null)
                ),
                saveInto: ri!nomination.isReadyForOnboarding,
                disabled: or(
                  #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(ri!selectedGroup),
                  #"_a-0000e723-cc8a-8000-9c0d-011c48011c48_4472947"(
                    nomination: ri!nomination,
                    currentReview: "isReadyForOnboarding"
                  ),

                )
              )
            }
          )
        }
      )
    },
    showWhen: ri!showWhen,
    style: "INFO",
    shape: "ROUNDED",
    height: "SHORT"
  )
)
